<?php
declare(strict_types=1);
namespace EPejabat\Modules\EForms;
use EPejabat\Core\{AccessDenied,Core,Support,Database,Authorization,InstallationKey};
final class VisualWeb {
 private static function e($s):string{return Support::escape((string)$s);}
 private static function json(array $r):never {header('Content-Type: application/json');header('Cache-Control: no-store');echo json_encode($r,JSON_THROW_ON_ERROR|JSON_HEX_TAG);exit;}
 private static function pdf(array $s):never {header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="original-form.pdf"');header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');header("Content-Security-Policy: sandbox");readfile($s['path']);exit;}
 public static function routes(\PDO $p,int $u):?string {
  if(!Visual::ready($p))return null;Core::module($p,'eforms');
  if($_SERVER['REQUEST_METHOD']==='POST'&&str_starts_with((string)($_POST['action']??''),'visual_')){Support::checkCsrf();$a=$_POST['action'];
   if($a==='visual_upload'){$id=Visual::upload($p,$u,Core::id($_POST['organisation_id']??null),$_FILES['pdf']??[]);Support::redirect('/eforms?studio=new&source='.$id);}
   if($a==='visual_save'){$id=Visual::save($p,$u,Core::id($_POST['organisation_id']??null),Support::post('title',190),json_decode(Support::post('fields_json',150000),true,64,JSON_THROW_ON_ERROR),json_decode(Support::post('workflow_json',5000),true,32,JSON_THROW_ON_ERROR),Support::post('acknowledgement',1000),Core::id($_POST['id']??null,true),Core::id($_POST['source_id']??null,true),json_decode(Support::post('visual_json',200000),true,64,JSON_THROW_ON_ERROR),Core::id($_POST['expected_version']??null,true));Support::redirect('/eforms?studio='.$id);}
   if($a==='visual_restore'||$a==='visual_duplicate'){$id=Visual::copyRevision($p,$u,Core::id($_POST['id']??null),Core::id($_POST['version_id']??null),$a==='visual_duplicate');Support::redirect('/eforms?studio='.$id);}
  }
  if(isset($_GET['original']))self::pdf(Visual::source($p,$u,Core::id($_GET['original'])));
  if(isset($_GET['original_submission'])){$r=Service::get($p,$u,Core::id($_GET['original_submission']));$b=Visual::binding($p,(int)$r['version_id']);if(!$b||!$b['source_id'])throw new \RuntimeException('PDF asal tiada.');self::pdf(Visual::source($p,$u,(int)$b['source_id'],false));}
  if(isset($_GET['print_original'])){$d=Visual::printData($p,$u,Core::id($_GET['print_original']));return '<h2>Cetakan PDF asal</h2><p>Versi submission dikekalkan. Perakuan pelulus hanya tersedia selepas approval.</p><div id="visual-print"></div>'.self::data($d).self::assets();}
  if(isset($_GET['studio']))return self::studio($p,$u,$_GET['studio']==='new'?null:Core::id($_GET['studio']));return null;
 }
 private static function assets():string {return '<link rel="stylesheet" href="/assets/eforms-visual.css?v='.substr(hash_file('sha256',APP_ROOT.'/assets/eforms-visual.css'),0,16).'"><script type="module" src="/assets/eforms-visual.mjs?v='.substr(hash_file('sha256',APP_ROOT.'/assets/eforms-visual.mjs'),0,16).'"></script>';}
 private static function data(array $d):string{return '<script type="application/json" id="visual-data">'.json_encode($d,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR).'</script>';}
 private static function post(string $action,string $fields,string $button):string{return '<form method="post"><input type="hidden" name="csrf" value="'.Support::csrf().'"><input type="hidden" name="action" value="'.$action.'">'.$fields.'<button>'.$button.'</button></form>';}
 public static function studio(\PDO $p,int $u,?int $id):string {
  $orgs=[];foreach($p->query('SELECT id,name FROM organisations WHERE is_active=1 ORDER BY name')->fetchAll() as $o){try{Service::permit($p,$u,'templates.manage',(int)$o['id']);$orgs[]=$o;}catch(\RuntimeException $e){}}if(!$orgs)throw new AccessDenied('Admin Form Builder diperlukan.');
  $r=$id?Database::query($p,'SELECT t.title,t.status,t.organisation_id,v.* FROM eforms_templates t JOIN eforms_versions v ON v.template_id=t.id WHERE t.id=? ORDER BY v.version DESC LIMIT 1',[$id])->fetch():null;if($id&&!$r)throw new \RuntimeException('Template tidak wujud.');if($r)Service::permit($p,$u,'templates.manage',(int)$r['organisation_id']);
  $binding=$r?Visual::binding($p,(int)$r['id']):null;$source=$binding['source_id']??null;if(!$r&&isset($_GET['source']))$source=Core::id($_GET['source']);$s=$source?Visual::source($p,$u,(int)$source):null;$org=(int)($r['organisation_id']??$s['organisation_id']??$orgs[0]['id']);
  $staff=[];foreach(Database::query($p,'SELECT u.id,s.full_name AS name FROM users u JOIN staff_profiles s ON s.staff_identity_id=u.staff_identity_id WHERE u.is_active=1 ORDER BY s.full_name')->fetchAll() as $a){$scopes=[];foreach($orgs as $o){try{Service::permit($p,(int)$a['id'],'submissions.review',(int)$o['id']);$scopes[]=(int)$o['id'];}catch(\RuntimeException $e){}}if($scopes){$a['orgs']=$scopes;$staff[]=$a;}}
  $owners=[];foreach(Database::query($p,'SELECT u.id,s.full_name AS name FROM users u JOIN staff_profiles s ON s.staff_identity_id=u.staff_identity_id WHERE u.is_active=1')->fetchAll() as $person){$scopes=[];foreach($orgs as $o){try{Service::permit($p,(int)$person['id'],'templates.manage',(int)$o['id']);$scopes[]=(int)$o['id'];}catch(\RuntimeException $e){}}if($scopes){$person['orgs']=$scopes;$owners[]=$person;}}
  $d=['id'=>$id,'expected_version'=>$r['id']??null,'source_id'=>$source,'pdf_url'=>$s?'/eforms?original='.$source:null,'sha256'=>$s['sha256']??null,'organisation_id'=>$org,'orgs'=>$orgs,'title'=>$r['title']??'Borang baharu','fields'=>$r?json_decode($r['schema_json'],true):[],'steps'=>$r?json_decode($r['workflow_json'],true):[],'definition'=>$binding['definition']??['pages'=>[],'maps'=>[],'review_confirmed'=>false],'acknowledgement'=>$r['acknowledgement']??'Saya mengesahkan maklumat ini benar.','owners'=>$owners,'actor_id'=>$u,'staff'=>$staff,'types'=>Schema::TYPES,'csrf'=>Support::csrf(),'autofill'=>Visual::autofill($p,$u)];
  $h='<h2>Smart Form Studio</h2><p>PDF asal → Draf cadangan → Sunting → Workflow → Pemetaan → Semak → Publish</p><div id="visual-studio"></div>'.self::data($d).self::assets();
  if(!$r){$options='';foreach($orgs as $o)$options.='<option value="'.$o['id'].'">'.self::e($o['name']).'</option>';$h.='<details open><summary>Import PDF baharu</summary><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="'.Support::csrf().'"><input type="hidden" name="action" value="visual_upload"><label>Organisasi<select name="organisation_id">'.$options.'</select></label><label>PDF asal (10 MB, 30 halaman maksimum)<input type="file" name="pdf" accept="application/pdf" required></label><p>Gunakan borang kosong. Buang data peribadi daripada salinan borang sebelum import. Scanned PDF boleh dipetakan manual; OCR tidak terbina.</p><button>Upload PDF</button></form></details>';}
  if($r){$h.='<h3>Versi dan penerbitan</h3><p>Status: '.self::e($r['status']).' · Versi '.$r['version'].'</p>';foreach(['1'=>'Publish selepas semakan','0'=>'Unpublish / Archive'] as $active=>$label)$h.=self::post('publish','<input name="id" type="hidden" value="'.$id.'"><input name="active" type="hidden" value="'.$active.'">',$label);$versions=Database::query($p,'SELECT id,version,created_at FROM eforms_versions WHERE template_id=? ORDER BY version DESC',[$id])->fetchAll();$opts='';foreach($versions as $v)$opts.='<option value="'.$v['id'].'">Versi '.$v['version'].' · '.self::e($v['created_at']).'</option>';$base='<input type="hidden" name="id" value="'.$id.'"><label>Versi asal<select name="version_id">'.$opts.'</select></label>';$h.=self::post('visual_restore',$base,'Restore sebagai draf baharu').self::post('visual_duplicate',$base,'Duplicate template');$count=Database::query($p,'SELECT COUNT(*) FROM eforms_submissions s JOIN eforms_versions v ON v.id=s.version_id WHERE v.template_id=?',[$id])->fetchColumn();$h.='<p>Jumlah penggunaan semua versi: '.(int)$count.'</p>';}
  return $h;
 }
 public static function field(array $f,mixed $v,bool $editable):?string {
  $e=fn($x)=>self::e($x);$type=$f['type'];$name='values['.$f['key'].']';$label=$e($f['label']).(!empty($f['required'])?' *':'');
  if(!$editable&&is_array($v))return '<p><strong>'.$label.'</strong>: '.$e(json_encode($v,JSON_UNESCAPED_UNICODE)).'</p>';
  if(!$editable)return null;
  switch($type){case 'pagebreak':return '<hr><h3>'.$label.'</h3>';case 'signature':return '<label><input type="checkbox" name="'.$name.'" value="1"'.($v==='1'?' checked':'').'>'.$label.' (perakuan digital)</label>';
   case 'searchable':$h='<label>'.$label.'<input name="'.$name.'" list="opts-'.$f['key'].'" value="'.$e($v).'"><datalist id="opts-'.$f['key'].'">';foreach($f['options'] as $o)$h.='<option value="'.$e($o).'">';return $h.'</datalist></label>';
   case 'multiselect':$h='<fieldset><legend>'.$label.'</legend>';foreach($f['options'] as $o)$h.='<label><input type="checkbox" name="'.$name.'[]" value="'.$e($o).'"'.(in_array($o,is_array($v)?$v:[],true)?' checked':'').'>'.$e($o).'</label>';return $h.'</fieldset>';
   case 'table':$h='<fieldset><legend>'.$label.'</legend><div data-repeat-table data-key="'.$f['key'].'" data-max="'.$f['max_rows'].'" data-columns="'.$e(json_encode($f['columns'])).'"></div><script type="application/json" data-table-values="'.$f['key'].'">'.json_encode(is_array($v)?$v:[],JSON_HEX_TAG|JSON_HEX_AMP).'</script></fieldset>';return $h;
  }return null;
 }
}
